export function getPlayerById(id: string): Player | undefined {
  return players.find((player) => player.id === id);
}

export function getPlayerByPromoSlug(slug: string): Player | undefined {
  const normalizedSlug = createPlayerSlug(slug);
  return players.find((player) => {
    const candidates = [
      player.id,
      player.slug,
      player.fullName,
      player.displayName,
      ...(player.searchAliases ?? []),
      ...(player.acceptedAnswers ?? [])
    ].filter((candidate): candidate is string => Boolean(candidate));

    return candidates.some((candidate) => createPlayerSlug(candidate) === normalizedSlug);
  });
}

export function createPlayerSlug(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function isPlayerExcluded(player: Player): boolean {
  return player.exclude === true;
}

export function getLaunchPlayerPool(): Player[] {
  return players.filter((player) => !isPlayerExcluded(player));
}

export function getCasualPlayerPool(): Player[] {
  return getLaunchPlayerPool().filter((player) => player.fameTier === "Elite" || player.fameTier === "Global");
}

export function getUltraPlayerPool(): Player[] {
  return getLaunchPlayerPool();
}
